import numpy as np

def expm_eig(A, t):
    """Return e^(At), assuming A is diagonalisable."""
    A = np.asarray(A, dtype=float)
    vals, X = np.linalg.eig(A)
    E = np.diag(np.exp(vals * t))
    return np.real(X @ E @ np.linalg.inv(X))


def solve_system(A, u0, t):
    """Return u(t) for u' = A u, starting at u0."""
    return expm_eig(A, t) @ np.asarray(u0, dtype=float)
